import{U as e,W as t,nt as n,t as r}from"./chunks/framework.CPHJXLir.js";import"./chunks/assets.JoaDwx61.js";var i=JSON.parse(`{"title":"Hello World: Creating Your First Business Central Extension","description":"","frontmatter":{},"headers":[],"relativePath":"installation-and-setup/hello-world.md","filePath":"installation-and-setup/hello-world.md"}`),a={name:`installation-and-setup/hello-world.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="hello-world-creating-your-first-business-central-extension" tabindex="-1">Hello World: Creating Your First Business Central Extension <a class="header-anchor" href="#hello-world-creating-your-first-business-central-extension" aria-label="Permalink to “Hello World: Creating Your First Business Central Extension”">​</a></h1><p>In this walkthrough, we&#39;ll create a simple AL extension for Microsoft Dynamics 365 Business Central. The extension will display a message when the Customer List page opens.</p><p>We&#39;ll use our locally installed Business Central 27.12 environment.</p><h2 id="_1-create-an-al-project" tabindex="-1">1. Create an AL Project <a class="header-anchor" href="#_1-create-an-al-project" aria-label="Permalink to “1. Create an AL Project”">​</a></h2><h3 id="step-1-create-a-project-folder" tabindex="-1">Step 1: Create a project folder <a class="header-anchor" href="#step-1-create-a-project-folder" aria-label="Permalink to “Step 1: Create a project folder”">​</a></h3><ol><li><p>Create a folder named <code>HelloWorldBC</code>.</p></li><li><p>Copy its absolute path, for example:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>C:\\BC-Development\\HelloWorldBC</span></span></code></pre></div></li><li><p>Open Visual Studio Code (VS Code).</p></li></ol><h3 id="step-2-generate-the-project" tabindex="-1">Step 2: Generate the project <a class="header-anchor" href="#step-2-generate-the-project" aria-label="Permalink to “Step 2: Generate the project”">​</a></h3><ol><li>Press <code>Ctrl + Shift + P</code> to open the Command Palette.</li><li>Type <code>AL: Go!</code> and select the command.</li><li>Follow the prompts to select the project folder and target platform.</li></ol><p><strong>Server selection:</strong> The prompt&#39;s position in the sequence may vary. When asked to select a server, choose <strong>Your own server</strong>, since we&#39;re targeting a local Business Central installation.</p><p><strong>Target platform:</strong> Select the appropriate option for your installed Business Central version. In this example, we&#39;re using Business Central 27.12.</p><p>The command scaffolds the project, generating files such as:</p><ul><li><code>app.json</code> — defines the extension&#39;s metadata, version, dependencies, and compatibility settings.</li><li><code>HelloWorld.al</code> — contains our AL source code.</li><li><code>.vscode/launch.json</code> — configures the connection used for publishing and debugging.</li></ul><p>If <code>launch.json</code> isn&#39;t generated, try reloading VS Code using <code>Developer: Reload Window</code> from the Command Palette, then run <code>AL: Go!</code> again.</p><h3 id="step-3-configure-the-connection" tabindex="-1">Step 3: Configure the connection <a class="header-anchor" href="#step-3-configure-the-connection" aria-label="Permalink to “Step 3: Configure the connection”">​</a></h3><p>Open <code>.vscode/launch.json</code>.</p><p>The generated configuration may contain example values. Update them to match your local Business Central installation.</p><p>For example, the relevant properties may look like this:</p><div class="language-json"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Your own server&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;request&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;launch&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;al&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;environmentType&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;OnPrem&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;server&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;http://localhost:8080/BC270&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;serverInstance&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;BC270&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;authentication&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Windows&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;startupObjectId&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">22</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;startupObjectType&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Page&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;breakOnError&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;All&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;launchBrowser&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;tenant&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;default&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>These are illustrative settings based on our local environment. Preserve the other properties generated by VS Code, and verify the server URL and instance against your actual configuration.</p><p><strong>Important:</strong> The Development Service port and web client port serve different purposes. In our environment, the Development Service is accessible at <code>localhost:8080</code>. Don&#39;t substitute the web client&#39;s URL without verifying the configuration.</p><h3 id="step-4-identify-the-server-instance" tabindex="-1">Step 4: Identify the server instance <a class="header-anchor" href="#step-4-identify-the-server-instance" aria-label="Permalink to “Step 4: Identify the server instance”">​</a></h3><p>If you don&#39;t know your Business Central Server instance name, open PowerShell and run:</p><div class="language-powershell"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Get-Service</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> |</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    Where-Object</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        $_</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.DisplayName </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">-like</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;*Dynamics*&quot;</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> -or</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        $_</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.Name </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">-like</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;*BC*&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    } </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">|</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    Format-Table</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Name</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">,</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> DisplayName</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">,</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Status</span></span></code></pre></div><p><strong>What does this command do?</strong></p><ul><li><code>Get-Service</code> retrieves Windows services.</li><li><code>Where-Object</code> filters the results to services whose display names contain <code>Dynamics</code> or whose internal names contain <code>BC</code>.</li><li><code>Format-Table</code> displays the service name, display name, and current status in a table.</li></ul><p>Example output:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Name                             DisplayName                                             Status</span></span>
<span class="line"><span>----                             -----------                                             ------</span></span>
<span class="line"><span>BcastDVRUserService_16fd32       GameDVR and Broadcast User Service_16fd32              Stopped</span></span>
<span class="line"><span>MicrosoftDynamicsNavServer$BC270 Microsoft Dynamics 365 Business Central Server [BC270] Running</span></span>
<span class="line"><span>WebClient                        WebClient                                              Stopped</span></span></code></pre></div><p>In this example, the Business Central Server instance name is <code>BC270</code>, as shown in square brackets in the display name.</p><p>Use your actual instance name in <code>launch.json</code>.</p><h2 id="_2-download-symbols" tabindex="-1">2. Download Symbols <a class="header-anchor" href="#_2-download-symbols" aria-label="Permalink to “2. Download Symbols”">​</a></h2><h3 id="what-are-symbols" tabindex="-1">What are symbols? <a class="header-anchor" href="#what-are-symbols" aria-label="Permalink to “What are symbols?”">​</a></h3><p>Symbols are reference packages that describe objects exposed by Business Central and installed extensions.</p><p>For example, if your AL code references the standard <code>Customer</code> table or extends the <code>Customer List</code> page, the compiler needs information about those objects to validate your code.</p><p>Downloading symbols makes this reference information available to your development project.</p><h3 id="download-the-symbols" tabindex="-1">Download the symbols <a class="header-anchor" href="#download-the-symbols" aria-label="Permalink to “Download the symbols”">​</a></h3><ol><li>Press <code>Ctrl + Shift + P</code>.</li><li>Type <code>AL: Download Symbols</code>.</li><li>Select the command and wait for it to finish.</li></ol><p>If successful, the Output panel should display:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>All reference symbols have been downloaded.</span></span></code></pre></div><p>The downloaded packages will normally be stored in the project&#39;s <code>.alpackages</code> folder.</p><p>If the download fails, verify that:</p><ul><li>Your server address and instance name are correct.</li><li>The Development Service is enabled and accessible.</li><li>Your <code>app.json</code> targets a compatible Business Central application version.</li><li>Your authentication configuration matches the server.</li></ul><h2 id="_3-configure-app-json" tabindex="-1">3. Configure <code>app.json</code> <a class="header-anchor" href="#_3-configure-app-json" aria-label="Permalink to “3. Configure app.json”">​</a></h2><p>Before building the extension, confirm that your project targets the correct Business Central version.</p><p>Our environment is <strong>Business Central 27.12</strong>, with platform version <code>27.0.55363.0</code> and application version <code>27.12.55425.0</code>.</p><p>The relevant properties in <code>app.json</code> should be compatible with that environment. For example:</p><div class="language-json"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;platform&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;27.0.0.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;application&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;27.12.0.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;runtime&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;16.0&quot;</span></span></code></pre></div><p>These are version declarations, not the full installed build numbers. Keep the remaining generated metadata, including the extension ID and ID range.</p><p>For details, see Microsoft&#39;s <a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/devenv-choosing-runtime" target="_blank" rel="noreferrer">Choosing the AL runtime version</a> documentation.</p><h2 id="_4-customize-helloworld-al" tabindex="-1">4. Customize <code>HelloWorld.al</code> <a class="header-anchor" href="#_4-customize-helloworld-al" aria-label="Permalink to “4. Customize HelloWorld.al”">​</a></h2><p>Open <code>HelloWorld.al</code> and replace its contents with the following code:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>namespace DefaultPublisher.HelloWorldBC;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>using Microsoft.Sales.Customer;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>pageextension 50100 CustomerListExt extends &quot;Customer List&quot;</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    trigger OnOpenPage()</span></span>
<span class="line"><span>    begin</span></span>
<span class="line"><span>        Message(&#39;Hello World! This is my first published app.&#39;);</span></span>
<span class="line"><span>    end;</span></span>
<span class="line"><span>}</span></span></code></pre></div><h3 id="understanding-the-code" tabindex="-1">Understanding the code <a class="header-anchor" href="#understanding-the-code" aria-label="Permalink to “Understanding the code”">​</a></h3><table tabindex="0"><thead><tr><th>Code</th><th>Explanation</th></tr></thead><tbody><tr><td><code>namespace DefaultPublisher.HelloWorldBC;</code></td><td>Groups the object under a namespace to help organize and distinguish it from objects in other extensions.</td></tr><tr><td><code>using Microsoft.Sales.Customer;</code></td><td>Imports a namespace used to resolve relevant identifiers.</td></tr><tr><td><code>pageextension 50100 CustomerListExt</code></td><td>Declares a page extension with object ID <code>50100</code> and name <code>CustomerListExt</code>.</td></tr><tr><td><code>extends &quot;Customer List&quot;</code></td><td>Specifies the standard Business Central page that we&#39;re extending.</td></tr><tr><td><code>trigger OnOpenPage()</code></td><td>Defines code that executes when the page opens.</td></tr><tr><td><code>Message(...)</code></td><td>Displays a message to the user.</td></tr></tbody></table><p><strong>What&#39;s a page extension?</strong></p><p>Business Central provides standard pages, tables, and other application objects. A page extension lets us customize an existing page without modifying Microsoft&#39;s original object.</p><p>Here, we&#39;re extending the standard Customer List page and adding a message when it opens.</p><p>The object ID <code>50100</code> must fall within the ID range declared in <code>app.json</code> and must not conflict with another object in your extension.</p><h2 id="_5-build-and-run-the-extension" tabindex="-1">5. Build and Run the Extension <a class="header-anchor" href="#_5-build-and-run-the-extension" aria-label="Permalink to “5. Build and Run the Extension”">​</a></h2><ol><li>Save your files.</li><li>In VS Code, select <strong>Run → Run Without Debugging</strong>.</li><li>The AL extension will compile your project and attempt to publish it to the configured Business Central environment.</li><li>If publishing succeeds, the web client should open.</li><li>Navigate to the Customer List page.</li></ol><p>You should see:</p><p><img src="/hello-world.png" alt="Output" width="700" height="294"></p><p>If the build or publishing process fails, inspect the VS Code <strong>Problems</strong> panel and the <strong>Output</strong> panel for the AL extension&#39;s error details.</p><h3 id="what-you-ve-accomplished" tabindex="-1">What you&#39;ve accomplished <a class="header-anchor" href="#what-you-ve-accomplished" aria-label="Permalink to “What you&#39;ve accomplished”">​</a></h3><p>You&#39;ve created your first Business Central extension and experienced the essential AL development workflow:</p><ol><li>Scaffold an AL project.</li><li>Configure the connection to Business Central.</li><li>Download symbols.</li><li>Write AL code.</li><li>Compile and publish the extension.</li><li>Test the extension in the Business Central web client.</li></ol><h2 id="further-reading" tabindex="-1">Further Reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to “Further Reading”">​</a></h2><ul><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/devenv-get-started" target="_blank" rel="noreferrer">Get started with AL development</a></li><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/devenv-json-files" target="_blank" rel="noreferrer">AL project JSON files</a></li><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/devenv-json-launch-file" target="_blank" rel="noreferrer">AL launch configuration</a></li><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/devenv-choosing-runtime" target="_blank" rel="noreferrer">Choosing the AL runtime version</a></li><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/devenv-page-ext-object" target="_blank" rel="noreferrer">Page extension object</a></li><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/al-agent-tools/al-tool-download-symbols" target="_blank" rel="noreferrer">Download AL symbols</a></li></ul>`,67)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};